	/**
	 * Default Constructor
	 */
    public LabResultService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new LabResultEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(LabResultRepository.class) );
		this.validator		= applicationContext.getBean(LabResultValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		LabResult
	 */
		public LabResult createLabResult( CreateLabResultCommand command ) {

		LabResult entity = new LabResult();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setLabResultId( command.getLabResultId() );
            entity.setResultCode( command.getResultCode() );
            entity.setIssuedDate( command.getIssuedDate() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of LabResult {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateLabResultCommand
	 * @return		LabResult
	 */
	public LabResult updateLabResult( UpdateLabResultCommand command ) {

		LabResult entity = new LabResult();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setLabResultId( command.getLabResultId() );
            entity.setResultCode( command.getResultCode() );
            entity.setIssuedDate( command.getIssuedDate() );
            entity.setLaboratoryOrder( command.getLaboratoryOrder() );
            entity.setObservations( command.getObservations() );
            entity.setLaboratory( command.getLaboratory() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of LabResult {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteLabResultCommand
	 */
	public void delete( DeleteLabResultCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getLabResultId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of LabResult {0} ", id );

	}

	/**
	 * Method to retrieve the LabResult via LabResultFetchOneSummary
	 * @param 	summary LabResultFetchOneSummary
	 * @return 	LabResultFetchOneResponse
	 */
	public LabResult getLabResult( LabResultFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LabResultFetchOneSummary arg cannot be null" );

		LabResult entity = null;
		UUID id = summary.getLabResultId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LabResult using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all LabResults
	 *
	 * @return 	List<LabResult>
	 */
    public List<LabResult> getAllLabResult() {
		List<LabResult> list = projector.findAll( new FindAllLabResultQuery() );
		return list;
	}

